<template>
  <Teleport to="body">
    <div v-if="open" class="fixed inset-0 z-40 flex items-center justify-center bg-slate-900/28 p-4 backdrop-blur-sm">
      <form
        class="w-full max-w-xl rounded-[28px] border border-white/70 bg-white/90 p-6 shadow-glass"
        @submit.prevent="submitForm"
      >
        <div class="mb-5 flex items-center justify-between">
          <div>
            <h2 class="text-xl font-semibold text-slate-900">{{ entry ? '编辑编辑器入口' : '新增编辑器入口' }}</h2>
            <p class="mt-1 text-sm text-slate-500">配置可内嵌或外链打开的 Web 编辑器页面。</p>
          </div>
          <button
            class="rounded-xl p-2 text-slate-400 hover:bg-slate-100 hover:text-slate-700"
            type="button"
            @click="$emit('close')"
          >
            <X class="size-5" />
          </button>
        </div>

        <div class="grid gap-4">
          <label class="grid gap-1.5 text-sm font-medium text-slate-700">
            名称
            <input
              v-model="form.name"
              class="rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm outline-none transition focus:border-navigator-blue"
              maxlength="40"
              placeholder="资产转换工作台"
            />
          </label>

          <label class="grid gap-1.5 text-sm font-medium text-slate-700">
            URL
            <input
              v-model="form.url"
              class="rounded-2xl border bg-white px-4 py-3 text-sm outline-none transition"
              :class="urlError ? 'border-red-300 focus:border-red-400' : 'border-slate-200 focus:border-navigator-blue'"
              placeholder="https://editor.example.com/workbench"
            />
            <span v-if="urlError" class="text-xs text-red-500">{{ urlError }}</span>
          </label>

          <label class="grid gap-1.5 text-sm font-medium text-slate-700">
            打开方式
            <select
              v-model="form.openMode"
              class="rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm outline-none transition focus:border-navigator-blue"
            >
              <option value="iframe">iframe（内嵌）</option>
              <option value="external">external（外链新标签）</option>
            </select>
          </label>

          <div class="grid grid-cols-[96px_1fr] gap-3 max-sm:grid-cols-1">
            <label class="grid gap-1.5 text-sm font-medium text-slate-700">
              图标
              <input
                v-model="form.icon"
                class="rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm outline-none transition focus:border-navigator-blue"
                maxlength="8"
                placeholder="🎛️"
              />
            </label>
            <label class="grid gap-1.5 text-sm font-medium text-slate-700">
              描述
              <input
                v-model="form.description"
                class="rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm outline-none transition focus:border-navigator-blue"
                maxlength="90"
                placeholder="用于搭建、调试与发布 3D 场景的内部编辑器。"
              />
            </label>
          </div>

          <template v-if="form.openMode === 'iframe'">
            <label
              class="flex items-center justify-between rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-700"
            >
              <span>
                <span class="font-medium">启用 iframe sandbox</span>
                <span class="mt-1 block text-xs text-slate-500">默认最小权限运行，降低外部页面影响导航页的风险。</span>
              </span>
              <input v-model="form.sandbox" class="size-5 accent-navigator-blue" type="checkbox" />
            </label>

            <label class="grid gap-1.5 text-sm font-medium text-slate-700">
              iframe allow 权限
              <input
                v-model="form.allow"
                class="rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm outline-none transition focus:border-navigator-blue"
                placeholder="clipboard-read; clipboard-write; fullscreen"
              />
            </label>
          </template>
        </div>

        <div class="mt-6 flex justify-end gap-3">
          <button
            class="rounded-2xl border border-slate-200 bg-white px-4 py-2.5 text-sm text-slate-600 hover:bg-slate-50"
            type="button"
            @click="$emit('close')"
          >
            取消
          </button>
          <button
            class="rounded-2xl bg-navigator-blue px-5 py-2.5 text-sm font-medium text-white shadow-card hover:bg-navigator-deep"
            type="submit"
          >
            保存配置
          </button>
        </div>
      </form>
    </div>
  </Teleport>
</template>

<script setup lang="ts">
import { reactive, ref, watch } from 'vue';
import { X } from 'lucide-vue-next';

import { DEFAULT_IFRAME_ALLOW } from '../config/editors.default';
import { useEditorsStore } from '../store/editors';
import type { EditorEntry } from '../types/editor-entry';
import { validateEditorUrl } from '../utils/url';

const props = defineProps<{
  open: boolean;
  entry: EditorEntry | null;
}>();

const emit = defineEmits<{
  close: [];
  saved: [entry: EditorEntry];
}>();

const store = useEditorsStore();
const urlError = ref('');
const form = reactive({
  name: '',
  url: '',
  openMode: 'iframe' as 'iframe' | 'external',
  icon: '🛠️',
  description: '',
  sandbox: true,
  allow: DEFAULT_IFRAME_ALLOW,
});

function syncForm() {
  form.name = props.entry?.name ?? '';
  form.url = props.entry?.url ?? '';
  form.openMode = props.entry?.openMode ?? 'iframe';
  form.icon = props.entry?.icon ?? '🛠️';
  form.description = props.entry?.description ?? '';
  form.sandbox = props.entry?.sandbox ?? true;
  form.allow = props.entry?.allow ?? DEFAULT_IFRAME_ALLOW;
  urlError.value = '';
}

function submitForm() {
  const validation = validateEditorUrl(form.url);
  urlError.value = validation.valid ? '' : (validation.message ?? 'URL 不合法。');

  if (!form.name.trim()) {
    urlError.value = urlError.value || '请先填写编辑器名称。';
    return;
  }

  if (!validation.valid) return;

  const payload = {
    name: form.name,
    url: validation.value,
    openMode: form.openMode,
    icon: form.icon,
    description: form.description,
    sandbox: form.openMode === 'iframe' ? form.sandbox : true,
    allow: form.openMode === 'iframe' ? form.allow : DEFAULT_IFRAME_ALLOW,
  };
  const savedEntry = props.entry ? store.updateEntry(props.entry.id, payload) : store.addEntry(payload);
  emit('saved', savedEntry);
}

watch(() => [props.open, props.entry?.id], syncForm, { immediate: true });
</script>
