/**
 * navigator 自身在所有部署环境中的固定路径后缀。
 * 运行时通过截掉此后缀得到当前环境的 base URL。
 *
 * 示例：
 *   location = https://res.cymini.qq.com/team6-base/dev/gs-viewer2/editor/navigator/index.html
 *   截掉 /editor/navigator 后 → https://res.cymini.qq.com/team6-base/dev/gs-viewer2
 */
const NAVIGATOR_PATH_SUFFIX = '/editor/navigator';

/**
 * 本地开发时的回退 base URL（线上 dev 环境）。
 * 本地调试 navigator 时，兄弟编辑器 iframe 指向线上 dev 版本，
 * 始终可用且无需关心各编辑器本地端口是否启动。
 */
const DEV_FALLBACK_BASE = 'https://res.cymini.qq.com/team6-base/dev/gs-viewer2';

/**
 * 从当前页面 URL 推导出部署环境的 base URL。
 *
 * 算法：在 pathname（不含 query/hash）中查找 NAVIGATOR_PATH_SUFFIX，
 * 取 origin + pathname 截断前缀部分。
 *
 * 降级策略：
 *   - 本地开发（localhost / 127.0.0.1）→ 返回 DEV_FALLBACK_BASE
 *   - 找不到后缀 → 返回 DEV_FALLBACK_BASE
 */
function getBaseUrl(): string {
  if (typeof window === 'undefined') return DEV_FALLBACK_BASE;

  const { origin, pathname, hostname } = window.location;

  // 本地开发环境：回退到线上 dev
  if (hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '0.0.0.0') {
    return DEV_FALLBACK_BASE;
  }

  // 在纯路径部分匹配，避免 query/hash 中的干扰
  const idx = pathname.toLowerCase().indexOf(NAVIGATOR_PATH_SUFFIX);
  if (idx === -1) {
    return DEV_FALLBACK_BASE;
  }
  // origin 不含尾部斜杠，pathname 以 / 开头 → origin + pathname[:idx]
  return origin + pathname.substring(0, idx);
}

/** 缓存 base URL，避免重复计算 */
let cachedBaseUrl: string | null = null;

/**
 * 获取当前部署环境的 base URL（带缓存）。
 *
 * 返回值示例：
 *   - "http://web-wide-world.space"
 *   - "https://res.cymini.qq.com/team6-base/dev/gs-viewer2"
 *   - "https://res.cymini.qq.com/team6-base/gs-viewer2"
 */
export function getDeployBaseUrl(): string {
  if (cachedBaseUrl === null) {
    cachedBaseUrl = getBaseUrl();
  }
  return cachedBaseUrl;
}

/**
 * 解析同部署环境下兄弟编辑器的完整 URL。
 *
 * @param relativePath - 相对于 base 的路径，如 "/editor/splat-studio/index.html"
 *                       （前导 / 可省略，函数内部会自动补齐）
 *
 * 运行时行为：
 *   - 线上环境：从 location 推导的 baseUrl + relativePath
 *   - 本地开发：DEV_FALLBACK_BASE + relativePath（指向线上 dev）
 *
 * 单一函数、单一参数，所有环境自动适配。
 */
export function resolveSiblingEditorUrl(relativePath: string): string {
  const base = getDeployBaseUrl();
  const normalizedPath = relativePath.startsWith('/') ? relativePath : '/' + relativePath;
  return base + normalizedPath;
}
