<template>
  <Teleport to="body">
    <div v-if="open" class="fixed inset-0 z-40 flex items-center justify-center bg-slate-900/28 p-4 backdrop-blur-sm">
      <section class="w-full max-w-lg rounded-[28px] border border-white/70 bg-white/90 p-6 shadow-glass">
        <div class="mb-5 flex items-center justify-between">
          <div>
            <h2 class="text-xl font-semibold text-slate-900">导入编辑器配置</h2>
            <p class="mt-1 text-sm text-slate-500">选择导出的 editors.json，按 ID 合并到本地配置。</p>
          </div>
          <button
            class="rounded-xl p-2 text-slate-400 hover:bg-slate-100 hover:text-slate-700"
            type="button"
            @click="$emit('close')"
          >
            <X class="size-5" />
          </button>
        </div>

        <div class="grid gap-4">
          <label class="grid gap-1.5 text-sm font-medium text-slate-700">
            冲突处理
            <select
              v-model="mode"
              class="rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm outline-none transition focus:border-navigator-blue"
            >
              <option value="overwrite">覆盖同 ID 配置</option>
              <option value="skip">跳过同 ID 配置</option>
            </select>
          </label>

          <label
            class="flex cursor-pointer flex-col items-center justify-center rounded-3xl border border-dashed border-navigator-blue/35 bg-blue-50/55 px-5 py-8 text-center transition hover:bg-blue-50"
          >
            <UploadCloud class="mb-3 size-8 text-navigator-blue" />
            <span class="text-sm font-medium text-slate-800">点击选择 editors.json</span>
            <span class="mt-1 text-xs text-slate-500">仅导入 version=1 的编辑器配置文件</span>
            <input class="sr-only" type="file" accept="application/json,.json" @change="handleFileChange" />
          </label>

          <div
            v-if="message"
            class="rounded-2xl border px-4 py-3 text-sm"
            :class="
              failed ? 'border-red-200 bg-red-50 text-red-600' : 'border-emerald-200 bg-emerald-50 text-emerald-700'
            "
          >
            {{ message }}
          </div>
        </div>

        <div class="mt-6 flex justify-end">
          <button
            class="rounded-2xl bg-navigator-blue px-5 py-2.5 text-sm font-medium text-white shadow-card hover:bg-navigator-deep"
            type="button"
            @click="$emit('close')"
          >
            完成
          </button>
        </div>
      </section>
    </div>
  </Teleport>
</template>

<script setup lang="ts">
import { ref } from 'vue';
import { UploadCloud, X } from 'lucide-vue-next';

import { useEditorsStore } from '../store/editors';
import type { ImportConflictMode } from '../types/editor-entry';
import { parseEditorExport } from '../utils/storage';

defineProps<{
  open: boolean;
}>();

defineEmits<{
  close: [];
}>();

const store = useEditorsStore();
const mode = ref<ImportConflictMode>('overwrite');
const message = ref('');
const failed = ref(false);

function handleFileChange(event: Event) {
  const input = event.target as HTMLInputElement;
  const file = input.files?.[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = () => {
    try {
      const exportFile = parseEditorExport(String(reader.result ?? ''));
      const summary = store.importFile(exportFile, mode.value);
      failed.value = false;
      message.value = `导入完成：新增 ${summary.added} 个，更新 ${summary.updated} 个，跳过 ${summary.skipped} 个。`;
    } catch (error) {
      console.error('导入编辑器配置失败。', error);
      failed.value = true;
      message.value = '导入失败，请确认文件是有效的 editors.json。';
    }
  };
  reader.onerror = () => {
    failed.value = true;
    message.value = '读取文件失败，请重新选择。';
  };
  reader.readAsText(file, 'utf-8');
  input.value = '';
}
</script>
