<template>
  <div
    class="flex h-full min-h-0 flex-col overflow-hidden border border-white/70 bg-white/70 shadow-glass backdrop-blur-xl"
  >
    <div v-if="entry" class="flex h-12 shrink-0 items-center justify-between gap-3 border-b border-slate-200/70 px-4">
      <div class="flex min-w-0 items-center gap-3">
        <span class="flex size-8 shrink-0 items-center justify-center rounded-xl bg-blue-50 text-lg">{{
          entry.icon || '🛠️'
        }}</span>
        <div class="min-w-0">
          <h2 class="truncate text-sm font-semibold text-slate-900">{{ entry.name }}</h2>
          <p class="truncate text-xs text-slate-500">{{ entry.url }}</p>
        </div>
      </div>
      <div class="flex shrink-0 items-center gap-2">
        <button
          class="rounded-xl border border-slate-200 bg-white px-3 py-1.5 text-xs text-slate-600 shadow-sm transition hover:bg-slate-50"
          type="button"
          @click="copyUrl"
        >
          <Copy class="mr-1 inline size-3.5" /> 复制
        </button>
        <button
          class="rounded-xl border border-slate-200 bg-white px-3 py-1.5 text-xs text-slate-600 shadow-sm transition hover:bg-slate-50"
          type="button"
          @click="refreshIframe"
        >
          <RefreshCw class="mr-1 inline size-3.5" /> 刷新
        </button>
        <a
          class="rounded-xl bg-navigator-blue px-3 py-1.5 text-xs font-medium text-white shadow-sm transition hover:bg-navigator-deep"
          :href="entry.url"
          target="_blank"
          rel="noreferrer"
        >
          <ExternalLink class="mr-1 inline size-3.5" /> 新标签打开
        </a>
        <button
          class="rounded-xl border border-slate-200 bg-white px-3 py-1.5 text-xs text-slate-600 shadow-sm transition hover:bg-slate-50"
          type="button"
          @click="exitEditor"
        >
          退出
        </button>
      </div>
    </div>

    <div class="relative min-h-0 flex-1 bg-slate-100/80">
      <iframe
        v-for="frame in frames"
        :key="`${frame.id}-${frame.key}`"
        class="h-full w-full border-0 bg-white"
        :class="frame.id === activeEditorId ? 'block' : 'hidden'"
        :allow="frame.allow"
        :sandbox="frame.sandboxAttr"
        :src="frame.url"
        :title="frame.title"
        @load="handleLoad(frame.id)"
      />

      <div
        v-if="entry && activeFrame?.loading"
        class="absolute inset-0 flex items-center justify-center bg-white/78 backdrop-blur-sm"
      >
        <div class="w-72 rounded-3xl border border-white bg-white/90 p-5 text-center shadow-card">
          <LoaderCircle class="mx-auto mb-3 size-8 animate-spin text-navigator-blue" />
          <p class="text-sm font-medium text-slate-800">正在载入 {{ entry.name }}</p>
          <p class="mt-1 text-xs text-slate-500">如果目标站点禁止 iframe 内嵌，可使用新标签打开。</p>
        </div>
      </div>

      <div
        v-if="entry && activeFrame?.blocked"
        class="absolute inset-x-6 bottom-6 rounded-3xl border border-amber-200 bg-amber-50/95 p-4 text-sm text-amber-900 shadow-card backdrop-blur"
      >
        <div class="flex items-start gap-3">
          <ShieldAlert class="mt-0.5 size-5 shrink-0" />
          <div>
            <p class="font-medium">该页面可能限制了 iframe 内嵌</p>
            <p class="mt-1 text-xs leading-5">
              浏览器会遵守目标站点的 X-Frame-Options 或 CSP 策略，前端无法绕过。请点击右上角“新标签打开”继续使用。
            </p>
          </div>
        </div>
      </div>

      <div v-if="!entry" class="absolute inset-0 flex items-center justify-center bg-white/72 backdrop-blur-[1px]">
        <div class="max-w-xl px-6 text-center">
          <div
            class="mx-auto mb-5 flex size-16 items-center justify-center rounded-3xl bg-gradient-to-br from-navigator-blue to-navigator-soft text-white shadow-card"
          >
            <Compass class="size-7" />
          </div>
          <h2 class="text-2xl font-semibold text-slate-900">选择一个编辑器开始工作</h2>
          <p class="mt-3 text-sm leading-7 text-slate-500">
            左侧列表会展示内置与自定义编辑器。你可以把资产转换、场景搭建、材质配置等 Web
            编辑器统一收纳到这里，点击后在右侧工作区直接打开。
          </p>
          <button
            class="mt-6 rounded-2xl bg-navigator-blue px-5 py-3 text-sm font-medium text-white shadow-card transition hover:-translate-y-0.5 hover:bg-navigator-deep"
            type="button"
            @click="emit('create-editor')"
          >
            <Plus class="mr-2 inline size-4" /> 新增团队编辑器入口
          </button>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { Compass, Copy, ExternalLink, LoaderCircle, Plus, RefreshCw, ShieldAlert } from 'lucide-vue-next';

import type { EditorEntry } from '../types/editor-entry';

const DEFAULT_IFRAME_URL = 'about:blank';
const DEFAULT_IFRAME_TITLE = '默认页';

interface CachedFrame {
  id: string;
  key: number;
  url: string;
  allow?: string;
  sandboxAttr?: string;
  title: string;
  loading: boolean;
  blocked: boolean;
  activated: boolean;
}

const props = defineProps<{
  entry?: EditorEntry;
}>();

const emit = defineEmits<{
  (event: 'create-editor'): void;
  (event: 'exit-editor', id: string): void;
  (event: 'activated-change', ids: string[]): void;
}>();

const frames = ref<CachedFrame[]>([]);
const timers = new Map<string, number>();

function notifyActivatedIds() {
  emit(
    'activated-change',
    frames.value.filter((frame) => frame.activated).map((frame) => frame.id),
  );
}

function toSandboxAttr(entry: EditorEntry) {
  return entry.sandbox === false
    ? undefined
    : 'allow-scripts allow-same-origin allow-forms allow-popups allow-downloads';
}

function findFrame(id: string) {
  return frames.value.find((frame) => frame.id === id);
}

function clearLoadingTimer(id: string) {
  const timer = timers.get(id);
  if (timer) {
    window.clearTimeout(timer);
    timers.delete(id);
  }
}

function startLoadingTimer(id: string) {
  const frame = findFrame(id);
  if (!frame?.activated) {
    return;
  }

  clearLoadingTimer(id);
  frame.loading = true;
  frame.blocked = false;

  const timer = window.setTimeout(() => {
    const nextFrame = findFrame(id);
    if (nextFrame?.loading && nextFrame.activated) {
      nextFrame.blocked = true;
      nextFrame.loading = false;
    }
    timers.delete(id);
  }, 3000);

  timers.set(id, timer);
}

function ensureFrame(entry: EditorEntry) {
  const sandboxAttr = toSandboxAttr(entry);
  const frame = findFrame(entry.id);

  if (!frame) {
    const createdFrame: CachedFrame = {
      id: entry.id,
      key: 0,
      url: entry.url,
      allow: entry.allow,
      sandboxAttr,
      title: entry.name,
      loading: true,
      blocked: false,
      activated: true,
    };
    frames.value = [...frames.value, createdFrame];
    notifyActivatedIds();
    startLoadingTimer(entry.id);
    return;
  }

  const shouldReload =
    !frame.activated ||
    frame.url !== entry.url ||
    frame.allow !== entry.allow ||
    frame.sandboxAttr !== sandboxAttr ||
    frame.title !== entry.name;

  frame.url = entry.url;
  frame.allow = entry.allow;
  frame.sandboxAttr = sandboxAttr;
  frame.title = entry.name;

  if (!frame.activated) {
    frame.activated = true;
    notifyActivatedIds();
  }

  if (shouldReload) {
    frame.key += 1;
    startLoadingTimer(entry.id);
  }
}

function handleLoad(id: string) {
  clearLoadingTimer(id);
  const frame = findFrame(id);
  if (frame) {
    frame.loading = false;
  }
}

function refreshIframe() {
  if (!props.entry) {
    return;
  }

  ensureFrame(props.entry);
  const frame = findFrame(props.entry.id);
  if (!frame) {
    return;
  }

  frame.key += 1;
  startLoadingTimer(frame.id);
}

function exitEditor() {
  if (!props.entry) {
    return;
  }

  const targetId = props.entry.id;
  const frame = findFrame(targetId);
  if (frame) {
    clearLoadingTimer(targetId);
    frame.activated = false;
    frame.url = DEFAULT_IFRAME_URL;
    frame.allow = undefined;
    frame.sandboxAttr = undefined;
    frame.title = DEFAULT_IFRAME_TITLE;
    frame.loading = false;
    frame.blocked = false;
    frame.key += 1;
    notifyActivatedIds();
  }

  emit('exit-editor', targetId);
}

function copyUrl() {
  if (!props.entry) {
    return;
  }

  navigator.clipboard?.writeText(props.entry.url).catch((error) => console.error('复制编辑器 URL 失败。', error));
}

const activeEditorId = computed(() => props.entry?.id ?? '');
const activeFrame = computed(() => (props.entry ? findFrame(props.entry.id) : undefined));

watch(
  () =>
    props.entry ? [props.entry.id, props.entry.url, props.entry.allow, props.entry.sandbox, props.entry.name] : null,
  () => {
    if (props.entry) {
      ensureFrame(props.entry);
    }
  },
  { immediate: true },
);

onBeforeUnmount(() => {
  Array.from(timers.keys()).forEach((id) => clearLoadingTimer(id));
});
</script>
