import { defineStore } from 'pinia';

import { DEFAULT_IFRAME_ALLOW, defaultEditors } from '../config/editors.default';
import type {
  EditableEditorPayload,
  EditorEntry,
  EditorExportFile,
  EditorStorageLayer,
  ImportConflictMode,
  ImportSummary,
} from '../types/editor-entry';
import {
  createEmptyStorageLayer,
  loadEditorStorage,
  normalizeEditorEntry,
  saveEditorStorage,
  serializeEditorExport,
} from '../utils/storage';
import { validateEditorUrl } from '../utils/url';
import { createEditorId } from '../utils/uuid';

interface EditorsState {
  layer: EditorStorageLayer;
}

function compareByCreatedAt(a: EditorEntry, b: EditorEntry): number {
  if (a.createdAt !== b.createdAt) {
    return a.createdAt - b.createdAt;
  }

  if (a.updatedAt !== b.updatedAt) {
    return a.updatedAt - b.updatedAt;
  }

  return a.id.localeCompare(b.id);
}

function buildOrderedIds(baseIds: string[], visibleEntries: EditorEntry[]): string[] {
  const visibleIds = visibleEntries.map((entry) => entry.id);
  const visibleSet = new Set(visibleIds);
  const kept = baseIds.filter((id) => visibleSet.has(id));
  const keptSet = new Set(kept);
  const appended = visibleIds.filter((id) => !keptSet.has(id));
  return [...kept, ...appended];
}

function mergeEntries(layer: EditorStorageLayer): EditorEntry[] {
  const userEntries = new Map(layer.entries.map((entry) => [entry.id, entry]));
  const builtinEntries = defaultEditors
    .filter((entry) => !layer.hiddenBuiltinIds.includes(entry.id))
    .map((entry) => userEntries.get(entry.id) ?? entry);
  const customEntries = layer.entries.filter((entry) => !defaultEditors.some((builtin) => builtin.id === entry.id));
  const visibleEntries = [...builtinEntries, ...customEntries].sort(compareByCreatedAt);
  const orderMap = new Map(layer.orderedIds.map((id, index) => [id, index]));

  return [...visibleEntries].sort((a, b) => {
    const aOrder = orderMap.get(a.id);
    const bOrder = orderMap.get(b.id);

    if (aOrder === undefined && bOrder === undefined) {
      return compareByCreatedAt(a, b);
    }

    if (aOrder === undefined) {
      return 1;
    }

    if (bOrder === undefined) {
      return -1;
    }

    return aOrder - bOrder;
  });
}

export const useEditorsStore = defineStore('editors', {
  state: (): EditorsState => ({
    layer: loadEditorStorage(),
  }),
  getters: {
    entries: (state): EditorEntry[] => mergeEntries(state.layer),
    visibleCount(): number {
      return this.entries.length;
    },
  },
  actions: {
    persist() {
      this.layer.orderedIds = buildOrderedIds(this.layer.orderedIds, this.entries);
      saveEditorStorage(this.layer);
    },
    findEntry(id: string): EditorEntry | undefined {
      return this.entries.find((entry) => entry.id === id);
    },
    addEntry(payload: EditableEditorPayload): EditorEntry {
      const entry = toSavedEntry(payload);
      this.layer.entries = [...this.layer.entries, entry];
      this.layer.orderedIds = buildOrderedIds(this.layer.orderedIds, this.entries);
      this.persist();
      return entry;
    },
    updateEntry(id: string, payload: EditableEditorPayload): EditorEntry {
      const existing = this.findEntry(id);

      if (!existing) {
        throw new Error('未找到需要更新的编辑器配置。');
      }

      const nextEntry = toSavedEntry(payload, existing);
      const existsInUserLayer = this.layer.entries.some((entry) => entry.id === id);
      this.layer.entries = existsInUserLayer
        ? this.layer.entries.map((entry) => (entry.id === id ? nextEntry : entry))
        : [...this.layer.entries, nextEntry];
      this.layer.hiddenBuiltinIds = this.layer.hiddenBuiltinIds.filter((hiddenId) => hiddenId !== id);
      this.persist();
      return nextEntry;
    },
    removeEntry(id: string) {
      const isBuiltin = defaultEditors.some((entry) => entry.id === id);
      this.layer.entries = this.layer.entries.filter((entry) => entry.id !== id);

      if (isBuiltin && !this.layer.hiddenBuiltinIds.includes(id)) {
        this.layer.hiddenBuiltinIds = [...this.layer.hiddenBuiltinIds, id];
      }

      if (!isBuiltin) {
        this.layer.orderedIds = this.layer.orderedIds.filter((orderedId) => orderedId !== id);
      }

      this.persist();
    },
    moveEntry(id: string, offset: -1 | 1) {
      const currentIds = this.entries.map((entry) => entry.id);
      const currentIndex = currentIds.indexOf(id);

      if (currentIndex < 0) {
        return;
      }

      const targetIndex = currentIndex + offset;
      if (targetIndex < 0 || targetIndex >= currentIds.length) {
        return;
      }

      [currentIds[currentIndex], currentIds[targetIndex]] = [currentIds[targetIndex], currentIds[currentIndex]];
      this.layer.orderedIds = currentIds;
      this.persist();
    },
    importFile(file: EditorExportFile, mode: ImportConflictMode): ImportSummary {
      const summary: ImportSummary = { added: 0, updated: 0, skipped: 0 };
      const nextEntries = [...this.layer.entries];

      file.entries.forEach((entryCandidate) => {
        const entry = normalizeEditorEntry(entryCandidate);
        if (!entry) {
          summary.skipped += 1;
          return;
        }

        const index = nextEntries.findIndex((item) => item.id === entry.id);
        if (index >= 0 && mode === 'skip') {
          summary.skipped += 1;
          return;
        }

        if (index >= 0) {
          nextEntries[index] = entry;
          summary.updated += 1;
          return;
        }

        nextEntries.push(entry);
        summary.added += 1;
      });

      this.layer = {
        version: 1,
        entries: nextEntries,
        hiddenBuiltinIds: Array.from(
          new Set([...(this.layer.hiddenBuiltinIds ?? []), ...(file.hiddenBuiltinIds ?? [])]),
        ),
        orderedIds: file.orderedIds ?? this.layer.orderedIds,
      };
      this.layer.orderedIds = buildOrderedIds(this.layer.orderedIds, this.entries);
      this.persist();
      return summary;
    },
    exportContent(): string {
      return serializeEditorExport({
        version: 1,
        entries: this.entries,
        hiddenBuiltinIds: this.layer.hiddenBuiltinIds,
        orderedIds: this.layer.orderedIds,
      });
    },
    resetUserLayer() {
      this.layer = createEmptyStorageLayer();
      this.persist();
    },
  },
});

function toSavedEntry(payload: EditableEditorPayload, existing?: EditorEntry): EditorEntry {
  const validation = validateEditorUrl(payload.url);

  if (!validation.valid) {
    throw new Error(validation.message ?? 'URL 不合法。');
  }

  const now = Date.now();

  return {
    id: existing?.id ?? createEditorId(),
    name: payload.name.trim(),
    url: validation.value,
    openMode: payload.openMode ?? existing?.openMode ?? 'iframe',
    icon: payload.icon?.trim() || '🛠️',
    description: payload.description?.trim(),
    sandbox: payload.sandbox ?? true,
    allow: payload.allow?.trim() || DEFAULT_IFRAME_ALLOW,
    builtin: existing?.builtin ?? false,
    createdAt: existing?.createdAt ?? now,
    updatedAt: now,
  };
}
