<template>
  <aside
    class="h-full w-[300px] border-r border-white/60 bg-white/45 p-4 backdrop-blur-xl max-[960px]:h-auto max-[960px]:w-full max-[960px]:border-r-0"
  >
    <div class="mb-4">
      <h2 class="text-[15px] font-semibold text-slate-900">编辑器入口</h2>
      <p class="text-xs text-slate-500">{{ entries.length }}个可用：已打开{{ activatedIds.length }}个</p>
    </div>

    <div v-if="entries.length" class="flex max-h-full flex-col gap-3 overflow-y-auto pr-1 max-[960px]:max-h-56">
      <EditorCard
        v-for="(entry, index) in orderedEntries"
        :key="entry.id"
        :active="entry.id === activeId"
        :activated="activatedIds.includes(entry.id)"
        :entry="entry"
        :can-move-up="index > 0"
        :can-move-down="index < orderedEntries.length - 1"
        @navigate="$emit('navigate', $event)"
        @edit="$emit('edit', $event)"
        @remove="confirmRemove"
        @move-up="$emit('move-up', $event)"
        @move-down="$emit('move-down', $event)"
      />
    </div>

    <div
      v-else
      class="rounded-2xl border border-dashed border-slate-300 bg-white/60 p-5 text-center text-sm text-slate-500"
    >
      暂无编辑器入口，请点击右上角新增。
    </div>
  </aside>
</template>

<script setup lang="ts">
import { computed } from 'vue';

import EditorCard from './EditorCard.vue';
import type { EditorEntry } from '../types/editor-entry';

const props = defineProps<{
  entries: EditorEntry[];
  activeId: string;
  activatedIds: string[];
}>();

const orderedEntries = computed(() => props.entries);

const emit = defineEmits<{
  navigate: [entry: EditorEntry];
  edit: [entry: EditorEntry];
  remove: [entry: EditorEntry];
  'move-up': [entry: EditorEntry];
  'move-down': [entry: EditorEntry];
}>();

function confirmRemove(entry: EditorEntry) {
  const action = entry.builtin ? '隐藏这个内置编辑器入口' : '删除这个自定义编辑器入口';
  if (window.confirm(`确定要${action}吗？`)) {
    emit('remove', entry);
  }
}
</script>
